PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JMEMBY 管理面板</title>
<style nonce="__NONCE__">
:root{font:16px system-ui;color:#e4eaf4;background:#111827;color-scheme:dark}body{margin:0}header{padding:24px 5%;border-bottom:1px solid #334155;display:flex;justify-content:space-between}h1{font-size:24px;margin:0}main{max-width:1150px;margin:30px auto;padding:0 20px}section{background:#1e293b;border:1px solid #334155;border-radius:14px;padding:24px;margin:20px 0}h2{font-size:20px}button,input,select{font:inherit;padding:10px 14px;border-radius:8px;border:1px solid #475569;background:#27364e;color:inherit}button{cursor:pointer}button:hover{background:#37537b}button:disabled{opacity:.5}nav,form,.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}input{max-width:100%}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:600px}td,th{padding:12px;text-align:left;border-bottom:1px solid #334155}td{overflow-wrap:anywhere}small{color:#a7b6ce}pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;font:inherit}#notice{color:#f5c97a;min-height:24px}#login{max-width:550px;margin:10vh auto}.cards{display:flex;gap:14px;flex-wrap:wrap}.card{background:#293a55;padding:20px;border-radius:10px;min-width:110px}.card strong{display:block;font-size:28px;margin-top:10px}[hidden]{display:none!important}@media(max-width:600px){main{padding:0 10px}section{padding:16px}input{width:100%;box-sizing:border-box}}
</style><header><div><h1>JMEMBY</h1><small>漫画服务管理面板</small></div><button id="logout" hidden>退出登录</button></header><main><div id="notice" role="status" aria-live="polite"></div>
<section id="login"><h2>管理员登录</h2><p>私聊 Telegram 机器人发送 <b>/web</b>，获取 5 分钟有效的一次性登录码。</p><form id="loginForm"><input id="code" type="password" autocomplete="one-time-code" aria-label="登录码" placeholder="粘贴一次性登录码" required><button>登录</button></form><small>仅项目配置中的管理员可以登录。</small></section>
<div id="panel" hidden><nav><button data-view="overview">概览</button><button data-view="tasks">下载队列</button><button data-view="users">用户管理</button><button data-view="history">下载来源</button><button id="refresh">刷新</button></nav>
<section id="overview"><h2>服务概览</h2><div id="stats" class="cards"></div><h2>注册设置</h2><div class="toolbar"><button id="registration"></button><button id="invite_mode"></button></div><small>阅读账号权限请在 Komga 管理。授权资格及白名单仍在群聊回复用户使用 /kk、/white。</small></section>
<section id="tasks" hidden><h2>下载队列</h2><select id="queue" aria-label="队列"><option value="all">全部队列</option><option value="white">白名单优先</option><option value="normal">普通队列</option></select><div id="taskTable" class="scroll"></div><div class="toolbar"><button id="taskPrev">上一页</button><span id="taskPage"></span><button id="taskNext">下一页</button></div></section>
<section id="users" hidden><h2>用户管理</h2><div id="userTable" class="scroll"></div><div class="toolbar"><button id="userPrev">上一页</button><span id="userPage"></span><button id="userNext">下一页</button></div></section>
<section id="history" hidden><h2>下载来源 · 最近 100 条任务</h2><form id="historyForm"><input id="historyQuery" maxlength="200" placeholder="漫画标题 / ID / 任务编号 / 用户 ID / 用户名" aria-label="搜索下载任务"><button>搜索</button><button type="button" id="historyClear">清空搜索</button></form><p><small>按提交时间倒序，包含所有任务状态；搜索全部历史并返回最近 100 条匹配任务。时间按浏览器本地时区显示。</small></p><p id="historyCount" role="status" aria-live="polite"></p><div id="historyTable" class="scroll"></div></section></div></main>
<script nonce="__NONCE__">
const el=id=>document.getElementById(id);let csrf='',view='overview',taskPage=1,userPage=1;
let historyQuery='',historyRequest=0;
const statuses={QUEUED:'排队中',DOWNLOADING:'下载中',PACKAGING:'整理中',IMPORT_PENDING:'入库中',COMPLETED:'已完成',FAILED:'失败',RETRY_WAIT:'等待重试',PAUSED_DISK:'磁盘暂停',CANCEL_REQUESTED:'取消中',CANCELLED:'已取消'};
function logged(v){el('login').hidden=v;el('panel').hidden=!v;el('logout').hidden=!v;}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok){if(r.status===401){logged(false);csrf='';}throw Error(d.error||'请求失败');}return d;}
async function safe(fn){el('notice').textContent='';try{await fn();}catch(e){el('notice').textContent=e.message;}}
function table(id,heads,rows){const t=document.createElement('table'),h=t.createTHead().insertRow();heads.forEach(x=>{const th=document.createElement('th');th.textContent=x;h.append(th);});const b=t.createTBody();rows.forEach(row=>{const tr=b.insertRow();row.forEach(x=>{const td=tr.insertCell();if(x instanceof Node)td.append(x);else td.textContent=x??'—';});});el(id).replaceChildren(t);if(!rows.length){const p=document.createElement('p');p.textContent='本页暂无记录';el(id).append(p);}}
function action(label,data){const b=document.createElement('button');b.textContent=label;b.onclick=()=>safe(async()=>{if(!confirm('确认'+label+'？'))return;b.disabled=true;try{await api('action',data);await load();el('notice').textContent='操作已完成';}finally{b.disabled=false;}});return b;}
async function load(){if(view==='history'){await loadHistory();}if(view==='overview'){const d=await api('overview');el('stats').replaceChildren();[['注册用户',d.total],['正常用户',d.active],['封禁用户',d.blocked],['管理员',d.admins],...Object.entries(d.tasks).map(([k,v])=>[statuses[k]||k,v])].forEach(([k,v])=>{const c=document.createElement('div');c.className='card';c.textContent=k;const s=document.createElement('strong');s.textContent=v;c.append(s);el('stats').append(c);});[['registration',d.registration_open,'新用户注册'],['invite_mode',d.invite_required,'邀请码要求']].forEach(([id,v,label])=>{el(id).textContent=label+'：'+(v?'开启':'关闭');el(id).onclick=()=>safe(async()=>{if(confirm('确认修改'+label+'？')){await api('action',{action:id,enabled:!v});await load();}});});}
if(view==='users'){const rows=await api('users?page='+userPage);table('userTable',['用户 ID','名称','组别','状态','操作'],rows.map(u=>[u.user_id,u.display_name+(u.username?' (@'+u.username+')':''),u.is_admin?'管理员':u.user_group==='white'?'白名单':'普通',u.blocked?'封禁':'正常',u.is_admin?'—':action(u.blocked?'解禁':'封禁',{action:u.blocked?'unban':'ban',user_id:u.user_id})]));el('userPage').textContent='第 '+userPage+' 页';el('userPrev').disabled=userPage===1;el('userNext').disabled=rows.length<10;}
if(view==='tasks'){const rows=await api('tasks?page='+taskPage+'&queue='+el('queue').value);table('taskTable',['漫画 / 任务编号','发起人 ID','队列','状态','进度','操作'],rows.map(t=>[t.title+' · JM'+t.source_id+' / '+t.id,t.user_id,t.priority?'白名单':'普通',statuses[t.status]||t.status,t.progress,['COMPLETED','FAILED','CANCELLED','CANCEL_REQUESTED'].includes(t.status)?'—':action('取消任务',{action:'cancel',task_id:t.id})]));el('taskPage').textContent='第 '+taskPage+' 页';el('taskPrev').disabled=taskPage===1;el('taskNext').disabled=rows.length<20;}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>safe(async()=>{view=b.dataset.view;['overview','tasks','users','history'].forEach(id=>el(id).hidden=id!==view);await load();}));
el('refresh').onclick=()=>safe(load);el('queue').onchange=()=>safe(async()=>{taskPage=1;await load();});for(const [id,delta,type] of [['taskPrev',-1,'tasks'],['taskNext',1,'tasks'],['userPrev',-1,'users'],['userNext',1,'users']])el(id).onclick=()=>safe(async()=>{if(type==='tasks')taskPage+=delta;else userPage+=delta;await load();});
el('loginForm').onsubmit=e=>{e.preventDefault();safe(async()=>{await api('login',{code:el('code').value});el('code').value='';await boot();});};el('logout').onclick=()=>safe(async()=>{await api('logout',{});csrf='';logged(false);});
async function loadHistory(){const request=++historyRequest;el('historyCount').textContent='加载中…';el('historyTable').replaceChildren();try{const d=await api('history?q='+encodeURIComponent(historyQuery));if(request!==historyRequest)return;table('historyTable',['漫画 / 来源 ID','任务编号','发起人 ID','姓名 / 用户名','队列','状态','提交时间（本地）'],d.tasks.map(t=>[t.title+' · '+t.source+':'+t.source_id,t.id,t.user_id,(t.display_name||'—')+(t.username?' (@'+t.username+')':''),t.priority?'白名单优先':'普通',statuses[t.status]||t.status,new Date(t.created_at*1000).toLocaleString()]));el('historyCount').textContent=(historyQuery?'搜索结果：':'最近任务：')+d.tasks.length+' 条（最多 '+d.limit+' 条）';}catch(e){if(request!==historyRequest)return;el('historyCount').textContent='加载失败，请重试';throw e;}}
el('historyForm').onsubmit=e=>{e.preventDefault();historyQuery=el('historyQuery').value.trim();safe(loadHistory);};
el('historyClear').onclick=()=>{historyQuery='';el('historyQuery').value='';safe(loadHistory);};
async function boot(){const s=await api('session');csrf=s.csrf;logged(true);await load();}safe(boot);
</script></html>'''
